INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('大模型工程师','信息技术 · 人工智能','[\"研发与微调大语言模型（预训练、SFT、RLHF），提升模型推理与对话能力\", \"搭建 RAG 知识库与智能体（Agent）工作流，把大模型接入真实业务\", \"优化模型推理成本与延迟，做模型评测与安全对齐\"]','大模型工程师是通用人工智能浪潮中最核心的岗位，负责让大模型从实验室走向千万级用户的真实产品，是各大科技公司竞相争夺的顶尖人才。','[\"深度学习与大模型原理（Transformer、注意力机制）\", \"PyTorch/DeepSpeed 等训练框架与分布式训练\", \"RAG、Agent、Prompt 工程实践\", \"模型评测、量化与推理加速\"]','[\"数学与算法功底\", \"论文跟踪与复现能力\", \"业务场景抽象能力\", \"跨团队协作沟通\"]','大模型人才缺口极大，资深大模型工程师年薪普遍 80 万以上，头部实验室与独角兽企业开出百万级 package；具备一线大模型项目经验者极度稀缺。','算法工程师 → 大模型工程师 → 模型负责人 → 首席科学家/AI 副总裁。','多模态大模型、端侧小模型、AI Agent 与具身智能是未来五年主战场，模型工程化与推理优化岗位增速最快。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('前端开发工程师','信息技术 · 软件开发','[\"使用 React/Vue 等框架开发网页与 H5 应用，实现产品界面与交互\", \"做移动端跨端开发（小程序、React Native、Flutter）与性能优化\", \"与设计师、后端协作，实现组件化、工程化的前端架构\"]','前端开发工程师负责用户看得见的所有界面，是互联网产品的门面工程师，从网页、小程序到桌面应用都出自他们之手。','[\"HTML/CSS/JavaScript/TypeScript 精通\", \"React/Vue 至少一门框架精通\", \"工程化（Vite/Webpack、CI/CD）与性能优化\", \"跨端开发（小程序/Flutter）经验\"]','[\"审美与用户体验意识\", \"与产品/设计的高效沟通\", \"组件化思维\", \"持续跟进前端新技术\"]','前端岗位需求量常年居技术岗位前列，资深前端与跨端专家薪资 40-80 万；懂 AI 应用开发（AI 编程工具、AI 交互界面）的前端更抢手。','前端开发 → 高级前端 → 前端架构师 → 技术负责人。','AI 辅助编程重塑开发流程，低代码与 AI 生成界面兴起，但懂架构与体验的高端前端需求不降反升。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('后端开发工程师','信息技术 · 软件开发','[\"设计与实现服务端业务逻辑、接口与数据库（MySQL/Redis/MQ）\", \"保障系统高并发、高可用与数据一致性\", \"参与微服务架构设计、性能调优与技术选型\"]','后端开发工程师构建系统的数据中枢与业务大脑，电商下单、支付转账、消息推送等所有核心链路都由后端支撑。','[\"Java/Go/Python/Node.js 至少一门精通\", \"MySQL/Redis/消息队列等中间件\", \"分布式系统与高并发设计\", \"Linux、Docker、K8s 部署运维\"]','[\"业务建模能力\", \"接口设计能力\", \"故障排查能力\", \"文档与协作能力\"]','后端是技术岗位中需求最稳定、天花板最高的方向之一，资深后端与架构师年薪 50-100 万；金融、电商、AI 基础设施领域溢价明显。','后端开发 → 高级后端 → 架构师 → 技术总监/CTO。','AI 应用后端（大模型接入）、云原生与 Serverless 是增长最快的细分方向。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('嵌入式软件工程师','信息技术 · 软件开发','[\"开发单片机/STM32/ARM 上的底层驱动与固件程序\", \"实现传感器、通信模组（4G/蓝牙/WiFi）与外围设备的接口控制\", \"做物联网终端、智能硬件产品的软件系统与功耗优化\"]','嵌入式软件工程师让硬件拥有智慧，从智能家居、可穿戴设备到汽车电子、工业控制器，所有智能设备的灵魂都运行在嵌入式代码之上。','[\"C/C++ 精通与指针/内存管理功底\", \"单片机/STM32/ARM 开发\", \"RTOS（FreeRTOS/RT-Thread）与驱动开发\", \"通信协议（UART/SPI/I2C/CAN）\"]','[\"硬件原理图阅读能力\", \"调试工具（示波器/逻辑分析仪）使用\", \"成本与功耗意识\", \"严谨细致\"]','智能硬件与汽车电子爆发带动嵌入式需求持续上涨，资深嵌入式工程师年薪 40-70 万，车规级与芯片原厂方向溢价高。','嵌入式工程师 → 系统工程师 → 技术专家 → 硬件产品负责人。','AIoT（AI+物联网）、车规级芯片软件、RISC-V 生态是嵌入式未来十年的三大增量。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('软件测试工程师','信息技术 · 软件开发','[\"编写测试用例与自动化测试脚本，覆盖功能/接口/性能/兼容性测试\", \"搭建自动化测试框架与 CI 持续集成流水线\", \"跟踪定位缺陷，输出质量报告，保障发布质量\"]','软件测试工程师是产品质量的守门员，随着自动化与 AI 测试的发展，已从手工点点点升级为懂开发、懂架构的质量工程专家。','[\"测试理论与用例设计方法\", \"Python/Java 自动化脚本（Selenium/Appium/接口测试）\", \"性能测试（JMeter）与缺陷管理\", \"CI/CD 流水线搭建\"]','[\"细致耐心与逆向思维\", \"业务理解能力\", \"沟通推动能力\", \"质量风险意识\"]','软件质量受重视程度持续提升，测开（测试开发）岗位薪资已接近开发岗，资深测开年薪 30-60 万；金融与车企质量岗需求旺盛。','功能测试 → 自动化测试 → 测试开发 → 质量负责人/测试架构师。','AI 生成测试用例与智能 fuzzing 兴起，测试左移（DevOps）与质量平台化是主流方向。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('机械设计工程师','智能制造 · 机械设计','[\"使用 SolidWorks/UG/CATIA 进行产品结构设计与三维建模\", \"出工程图纸、制定加工工艺，跟进样机试制与验证\", \"做结构强度仿真、公差分析与降本优化\"]','机械设计工程师是制造业的骨架师，从工业机器人、医疗器械到消费电子的结构件，所有实体产品的机械部分都由他们设计。','[\"机械原理、机械设计与工程力学\", \"SolidWorks/UG/CATIA 三维设计软件\", \"材料与加工工艺（注塑/钣金/机加工）\", \"结构仿真（ANSYS）与公差分析\"]','[\"空间想象力\", \"工程图纸规范意识\", \"跨部门协作（与电气/工艺/生产）\", \"成本意识\"]','制造业升级带来稳定需求，资深机械设计师年薪 25-50 万；机器人、半导体设备、医疗器械方向薪资明显更高。','助理工程师 → 机械工程师 → 主任工程师 → 技术总监。','机电软一体化要求提高，懂仿真与 AI 辅助设计的机械工程师竞争力显著增强。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('电气自动化工程师','智能制造 · 工业自动化','[\"设计 PLC 控制系统与电气原理图，编写自动化控制程序\", \"调试伺服、变频器、传感器等工控设备，完成产线自动化改造\", \"搭建 SCADA/MES 数据采集与监控系统\"]','电气自动化工程师让工厂产线自动运转，是智能工厂建设的核心力量，从汽车制造到食品医药产线都离不开自动化系统。','[\"PLC 编程（西门子/三菱/汇川）\", \"电气原理图设计（EPLAN/CAD）\", \"伺服/变频/传感器等工控产品\", \"工业通信（Profinet/Modbus/OPC UA）\"]','[\"现场调试能力\", \"故障诊断能力\", \"与机械/软件协同能力\", \"安全意识\"]','智能制造与灯塔工厂建设推动需求持续增长，资深自动化工程师年薪 25-45 万，新能源电池产线方向缺口最大。','自动化工程师 → 项目工程师 → 自动化经理 → 工厂数字化负责人。','工业机器人密度持续提升，AI 视觉质检、数字孪生产线是自动化工程师必须拥抱的新技能。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('机器视觉应用工程师','智能制造 · 工业质检','[\"搭建工业相机/镜头/光源的成像方案，完成标定与图像采集\", \"开发视觉检测算法（定位、测量、缺陷识别）并部署到产线\", \"联调 PLC/机器人，实现瑕疵品自动分拣与追溯\"]','机器视觉应用工程师给产线装上眼睛，用 AI 替代人工质检，3C 电子、锂电、光伏、汽车零部件产线已大规模部署视觉检测。','[\"机器视觉硬件选型与打光经验\", \"OpenCV/Halcon 视觉算法开发\", \"深度学习缺陷检测模型部署\", \"与 PLC/机器人通讯联调\"]','[\"图像分析与问题定位能力\", \"现场动手能力\", \"数据标注与模型迭代意识\", \"与产线人员沟通\"]','AI 质检渗透率快速提高，视觉应用工程师供不应求，年薪 25-50 万，有锂电/半导体项目经验者薪资上浮 30%。','视觉调试工程师 → 视觉算法工程师 → 视觉项目经理 → 智能制造方案专家。','大模型+小模型混合质检、无监督缺陷检测、3D 视觉是技术演进方向。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('增材制造工程师','智能制造 · 3D打印','[\"操作与维护金属/光固化/FDM 3D 打印设备，制定打印工艺参数\", \"进行三维模型修复、支撑设计与切片处理\", \"开发新材料新工艺，完成打印件后处理与性能检测\"]','增材制造（3D 打印）工程师是制造方式革命的实践者，在航空航天、医疗植入物、模具随形水路等领域，3D 打印已实现不可替代的应用。','[\"3D 打印工艺（SLM/SLS/SLA/FDM）\", \"Magics/切片软件与模型修复\", \"材料学基础（金属粉末/光敏树脂）\", \"后处理（热处理/机加工）与检测\"]','[\"三维空间思维\", \"工艺实验与数据分析能力\", \"质量意识\", \"跨学科学习能力\"]','3D 打印产业年增速超 20%，金属增材人才尤为稀缺，资深工程师年薪 25-45 万；航空航天与医疗齿科岗位附加值最高。','设备操作工程师 → 工艺工程师 → 增材研发工程师 → 技术专家。','多材料打印、大幅面金属打印、增材与减材复合制造是前沿方向。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('临床药师','医疗健康 · 药学服务','[\"审核处方与医嘱，提供用药咨询与药学监护\", \"开展治疗药物监测（TDM），制定个体化给药方案\", \"参与临床查房与多学科会诊，开展合理用药宣教\"]','临床药师从幕后走到病床前，与医师共同制定用药方案，是保障患者用药安全、促进合理用药的专业力量，三甲医院药学部核心岗位。','[\"药理学与临床药物治疗学\", \"处方审核与用药咨询技能\", \"TDM 与个体化给药\", \"药事管理与法规\"]','[\"医患沟通能力\", \"循证医学思维\", \"团队协作\", \"持续更新药学知识\"]','公立医院药事服务转型加速，临床药师需求稳步增长；资深临床药师年薪 20-40 万，肿瘤、抗感染、儿科专科药师尤为紧缺。','调剂药师 → 临床药师 → 专科临床药师 → 药学部主任。','药学门诊、互联网药学服务、AI 处方审核让药师服务价值持续放大。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('医学影像技师','医疗健康 · 医技','[\"操作 CT/MRI/DR/超声等大型影像设备完成检查扫描\", \"根据检查部位制定扫描参数与序列，保证图像质量\", \"配合影像医师完成增强检查、介入手术的影像支持\"]','医学影像技师是临床诊断的眼睛，精准的影像图像质量直接决定诊断准确性，是医院医技科室的中坚力量。','[\"影像设备操作与成像原理\", \"人体解剖学与检查部位规范\", \"对比剂使用与过敏反应处置\", \"辐射防护与设备质控\"]','[\"细致规范的操作习惯\", \"与患者沟通安抚能力\", \"应急处理能力\", \"设备故障判断\"]','影像设备持续普及与更新换代，影像技师需求稳定增长；大型设备上岗证持证技师年薪 15-30 万，PET/CT、MRI 技师紧缺。','影像技师 → 主管技师 → 影像科技术组长 → 设备科/医学工程方向。','AI 辅助阅片普及后，技师工作与诊断分工更清晰，操作规范与质控能力更重要。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('注册营养师','医疗健康 · 健康服务','[\"进行膳食调查与营养评估，制定个体化营养干预方案\", \"为慢病（糖尿病、高血压、肥胖）患者提供医学营养治疗\", \"开展社区/企业营养科普，设计团餐与月子餐营养配餐\"]','注册营养师用一日三餐守护健康，从临床营养支持到体重管理、运动营养，是健康中国行动重点发展的专业队伍。','[\"基础营养学与临床营养学\", \"膳食调查与营养评估工具\", \"慢病医学营养治疗（MNT）\", \"营养配餐软件与食谱设计\"]','[\"咨询沟通与行为干预能力\", \"科普写作能力\", \"跨学科协作（医生/护士/健身教练）\", \"亲和力\"]','超重肥胖人群超 50%，慢病管理需求爆发，注册营养师人才缺口达 400 万；资深营养师年薪 15-35 万，私人营养顾问按时收费。','临床营养师 → 专科营养师（减重/孕产/运动）→ 营养科主任/健康管理机构合伙人。','互联网+营养咨询、AI 配餐工具、功能食品研发为营养师打开多元收入渠道。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('公共卫生医师','医疗健康 · 预防医学','[\"开展疾病监测与疫情研判，制定防控方案\", \"组织预防接种、健康教育、慢病筛查等群体干预\", \"进行环境卫生、职业卫生、食品卫生监测与风险评估\"]','公共卫生医师是群体健康的前哨，新冠疫情防控让全社会认识到公卫体系的价值，他们通过预防关口前移守护千万人健康。','[\"流行病学与卫生统计学\", \"传染病防控与应急处理\", \"健康教育与健康促进\", \"环境卫生与职业卫生监测\"]','[\"数据分析能力\", \"现场流调组织能力\", \"公文写作与政策理解\", \"跨部门协调\"]','公卫体系建设投入持续加大，疾控中心、医院公卫科、海关卫检需求增加；公卫医师年薪 15-30 万，紧缺专业（流行病学）上浮。','公卫医师 → 科室骨干 → 疾控中心科长 → 卫健委管理岗。','智慧公卫（大数据监测）、医防融合、全球健康治理是未来公卫发展的关键词。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('人力资源管理师','现代服务 · 企业管理','[\"负责招聘配置、培训发展、绩效管理全模块工作\", \"设计薪酬激励体系与员工职业发展规划\", \"处理劳动关系，组织企业文化建设与人才盘点\"]','人力资源管理师是企业选育用留的设计师，从校园招聘到股权激励，从组织变革到企业文化，是连接战略与员工的桥梁。','[\"人力资源六大模块实操\", \"劳动法与劳动关系处理\", \"人才测评与面试评估技术\", \"薪酬绩效体系设计\"]','[\"沟通协调与共情能力\", \"数据分析（人效指标）能力\", \"组织协调与活动策划\", \"保密与职业操守\"]','所有规模以上企业都需要 HR，资深 HRBP 年薪 30-60 万；懂业务、懂数据的人力资源伙伴（HRBP）是晋升最快方向。','HR 专员 → HRBP → 人力资源经理 → 人力资源总监（HRD）。','AI 招聘筛选、数字化人效管理普及，HR 从事务性工作转向战略人才管理。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('电子商务师','现代服务 · 电商','[\"运营天猫/京东/抖音店铺，制定商品策略与营销活动\", \"分析流量、转化、复购数据，优化详情页与投放 ROI\", \"管理直播带货、短视频种草等内容电商业务\"]','电子商务师是线上生意的操盘手，从平台店铺到直播电商，用数据与内容把货卖给全国消费者，是数字经济最活跃的岗位群。','[\"电商平台规则与运营实操\", \"数据分析（生意参谋/蝉妈妈等工具）\", \"内容策划与直播运营\", \"直通车/千川等付费投放\"]','[\"市场敏感度\", \"文案与审美能力\", \"抗压与快速迭代能力\", \"供应链管理意识\"]','电商渗透率持续提升，资深运营年薪 20-50 万+业绩提成；直播电商、即时零售、跨境电商运营人才缺口大。','运营专员 → 店长 → 电商经理 → 电商总监/合伙人。','AI 生成商品素材、数字人直播、全域经营（公域+私域）是电商运营新范式。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('酒店管理师','现代服务 · 旅游酒店','[\"负责酒店前厅/客房/餐饮部门的运营管理与服务品质控制\", \"制定营收预算与营销策略，管理 OTA 渠道与会员体系\", \"培训服务团队，处理宾客投诉与突发事件\"]','酒店管理师是品质住宿体验的缔造者，从国际联号酒店到高端民宿，用标准化服务与温度化管理赢得宾客口碑。','[\"酒店运营管理体系与 SOP 标准\", \"收益管理与 OTA 渠道运营\", \"宾客关系管理与服务补救\", \"团队培训与排班管理\"]','[\"高情商与跨文化沟通\", \"突发事件应急能力\", \"成本控制意识\", \"品牌营销能力\"]','高端酒店与度假市场复苏，资深店总年薪 40-80 万+绩效；连锁化率提升带来大量中层管理岗位。','管培生 → 部门经理 → 驻店经理 → 酒店总经理/区域总监。','智慧酒店（无人前台、智能客房）、康养度假、酒店+长租融合业态兴起。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('旅游策划师','现代服务 · 旅游规划','[\"设计主题旅游线路与产品（研学、康养、亲子、定制游）\", \"踩线考察目的地，整合酒店/交通/景区资源定价\", \"运营私域客群，组织带队执行与风险管控\"]','旅游策划师是美好旅程的编剧，把目的地资源变成有故事、有体验的产品，是文旅融合时代创意与执行兼备的岗位。','[\"旅游产品设计能力与目的地知识\", \"成本核算与供应链议价\", \"私域运营与内容营销\", \"应急安全与合规意识\"]','[\"创意策划能力\", \"文案与视觉表达能力\", \"跨文化沟通\", \"体力与执行力\"]','文旅市场强劲复苏，定制游与研学游增速超 30%，资深旅游策划师年薪 15-35 万；掌握稀缺目的地资源者收入上不封顶。','旅游顾问 → 产品经理 → 线路总监 → 文旅公司合伙人。','AI 行程规划、内容种草驱动获客、银发康养旅游是行业新蓝海。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('银行客户经理','金融财会 · 银行金融','[\"维护企业与个人客户关系，提供存贷款、理财综合金融服务\", \"开展信贷尽职调查，撰写授信报告，防控不良风险\", \"完成存款、理财、信用卡等综合营销指标\"]','银行客户经理是银行价值创造的前线，连接资金供需两端，是金融业覆盖面最广、培养体系最成熟的岗位之一。','[\"信贷业务与风控知识\", \"财务报表分析\", \"金融产品知识（理财/基金/保险）\", \"客户资源开发与维护\"]','[\"沟通谈判能力\", \"合规与风险意识\", \"抗压能力\", \"本地人脉资源\"]','银行业转型期结构性分化，对公客户经理与私行顾问年薪 20-60 万；具备 CFA/AFP 证书与客户资源者优势明显。','柜员/客户经理 → 高级客户经理 → 支行副行长 → 支行行长。','财富管理转型加速，懂资产配置的理财经理取代传统推销角色。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('保险规划师','金融财会 · 保险','[\"分析家庭风险敞口，设计重疾、寿险、年金、财产保障组合\", \"为客户提供保单检视、理赔协助与家庭财务规划\"]','保险规划师是家庭风险管理的医生，用专业方案抵御疾病、意外与长寿风险，高素质规划师正成为保险业高质量发展的中坚。','[\"保险原理与产品条款精研\", \"家庭财务分析与需求诊断\", \"核保理赔流程\", \"法商与税务筹划基础\"]','[\"信任建立能力\", \"长期服务意识\", \"案例讲解能力\", \"自律与持续学习\"]','保险业精英化转型，MDRT 会员年薪普遍 30 万以上，顶尖规划师年入百万；养老金融爆发带来年金大单机遇。','保险顾问 → 资深规划师 → 团队总监 → 家族办公室顾问。','养老社区、保险金信托、AI 核保让保险规划更专业多元。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('风险管理师','金融财会 · 风控','[\"建立信用风险、市场风险、操作风险计量模型与预警体系\", \"审批准入业务，开展贷后/投后风险监测与压力测试\"]','风险管理师是金融机构的守门人，用模型与制度在收益与风险间寻找平衡，银行、券商、保险、互金全行业刚需岗位。','[\"风险计量（VaR/信用评级模型）\", \"金融法规与监管政策\", \"SQL/Python 数据分析\", \"财务报表与行业分析\"]','[\"审慎判断力\", \"跨部门推动力\", \"报告撰写能力\", \"职业独立性\"]','监管趋严使风控人才持续走俏，银行总行风控岗与券商风险管理岗年薪 30-70 万；模型风险管理（MRM）方向快速崛起。','风控专员 → 风险经理 → 风控总监 → 首席风险官（CRO）。','模型风险、气候风险（ESG）、反欺诈 AI 是风控领域新兴增长点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('资产评估师','金融财会 · 评估','[\"对房地产、机器设备、无形资产、企业价值进行评估测算\", \"撰写资产评估报告，支撑并购、抵押、上市、诉讼等经济行为\"]','资产评估师是资产价值的裁判员，服务于国企改制、并购重组、司法鉴证等场景，是财经领域含金量极高的执业资格岗位。','[\"资产评估准则与方法（成本法/市场法/收益法）\", \"财务分析与尽职调查\", \"房地产与机器设备知识\", \"评估报告撰写\"]','[\"现场勘查能力\", \"数据搜集与分析\", \"沟通协调（与委托方/监管）\", \"职业道德与独立性\"]','评估行业随资本市场与国资交易活跃而稳步增长，资深评估师年薪 25-50 万，证券评估资格机构签字评估师收入更高。','评估助理 → 项目经理 → 签字评估师 → 评估机构合伙人。','数据资产评估（知识产权、数据要素）成为评估行业全新增量市场。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('人民警察','法律政务 · 公安执法','[\"维护辖区治安，接处警、巡逻防控与纠纷调解\", \"侦办刑事案件，开展侦查取证与嫌疑人抓捕\"]','人民警察是平安中国的守护者，从社区民警到刑警、交警、网警，用忠诚与专业维护社会秩序与人民安全，是荣誉感与责任感并重的职业。','[\"法律法规与执法程序\", \"侦查取证与讯问技巧\", \"警务实战技能与应急处突\", \"信息化研判（大数据追逃）\"]','[\"政治素养与纪律性\", \"群众工作能力\", \"心理抗压能力\", \"团队协作\"]','公安队伍职业化改革深化，民警待遇与社会地位持续提升；专业技术警察（网安、技侦、法医）晋升通道畅通。','新警 → 警长 → 所队长 → 公安局领导；专业技术序列同步晋升。','智慧警务、AI 视频侦查、网络空间治理让现代警务科技含量持续提升。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('公证员','法律政务 · 法律服务','[\"办理合同、继承、委托、招投标等各类公证事项\", \"核实证明材料，询问当事人，制作公证笔录与公证书\"]','公证员是预防纠纷的法律卫士，通过公证证明法律行为、事实与文书的真实性合法性，在金融、房地产、家事领域作用关键。','[\"公证法与公证程序规则\", \"民商法与继承法实务\", \"证据审查与询问技巧\", \"公证信息化系统操作\"]','[\"严谨细致\", \"中立公正的职业操守\", \"沟通询问能力\", \"文书写作能力\"]','公证处体制改革推进，金融公证与家事公证需求增长，公证员年收入 20-40 万；涉外公证与赋强公证专家稀缺。','公证员助理 → 公证员 → 业务主任 → 公证处主任。','远程视频公证、区块链存证公证让服务更便捷，公证员从证明人转向综合法律服务者。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('知识产权代理师','法律政务 · 知识产权','[\"撰写专利申请文件，答复审查意见，办理商标注册与复审\", \"为企业提供专利布局、FTO 分析与侵权预警\"]','知识产权代理师是创新成果的护航者，把技术方案转化为受保护的法律权利，在创新驱动发展战略下成为技术与法律交叉的黄金职业。','[\"专利法/商标法与代理实务\", \"技术方案理解与检索分析\", \"专利撰写与答复技巧\", \"知识产权管理系统\"]','[\"技术理解力（理工背景加分）\", \"逻辑表达能力\", \"客户沟通能力\", \"英语文献阅读\"]','中国专利申请量全球第一，高质量代理人才严重不足，专利代理师年薪 20-50 万，涉外代理与无效诉讼专家收入更高。','代理师助理 → 执业代理师 → 资深代理师 → 代理机构合伙人/企业 IP 总监。','AI 辅助专利检索撰写普及，但高价值专利布局与海外维权仍需资深专家。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('企业合规师','法律政务 · 合规','[\"建立反商业贿赂、数据合规、出口管制等合规管理体系\", \"开展合规审查与尽职调查，组织合规培训与文化建设\"]','企业合规师是企业经营的安全带，在监管趋严与国际化经营背景下，帮助企业识别法律红线、建立合规防线，是近年最热门的新职业之一。','[\"公司法与行业监管法规\", \"合规管理体系（ISO 37301）\", \"内部调查与审计知识\", \"数据安全与个人信息保护法\"]','[\"风险识别能力\", \"跨部门协调能力\", \"培训宣讲能力\", \"原则性与判断力\"]','央企国企强制合规建设带动需求爆发，企业合规师年薪 30-80 万；涉外合规（出口管制、制裁）专家一票难求。','法务/审计 → 合规专员 → 合规经理 → 首席合规官（CCO）。','ESG 合规、算法合规、跨境数据流动合规成为合规体系新边疆。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('新闻记者','文化传媒 · 新闻传播','[\"采访报道时政、财经、社会等领域的突发与深度新闻\", \"核实信源，撰写消息、通讯、调查报道\"]','新闻记者是时代记录者，用脚步丈量现场、用笔触还原真相，在媒体深度融合时代向全媒体记者与调查记者转型。','[\"新闻采写与报道规范\", \"信源核实与事实核查\", \"音视频拍摄剪辑\", \"数据新闻与可视化\"]','[\"新闻敏感度\", \"写作表达能力\", \"现场应变\", \"职业伦理与法治意识\"]','主流媒体平台化改革中，具备视频化与数据化能力的记者竞争力强；资深调查记者与财经记者年收入 20-50 万。','记者 → 资深记者 → 部门主任 → 总编/新媒体负责人。','AI 辅助写作普及后，深度调查与原创现场报道的价值进一步凸显。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('广告策划师','文化传媒 · 广告营销','[\"洞察消费者需求，策划品牌定位与传播策略\", \"产出创意概念，撰写策划案并跟进拍摄制作落地\"]','广告策划师是品牌与消费者之间的翻译官，用洞察与创意让产品被记住、被喜爱，从传统 TVC 到社交传播都是他们的舞台。','[\"消费者洞察与品牌策略\", \"创意发想与文案能力\", \"媒介投放与效果评估\", \"提案与提案表达能力\"]','[\"审美与创意能力\", \"市场趋势敏感度\", \"项目管理能力\", \"说服沟通\"]','广告业向内容营销转型，懂品牌又懂增长的策划人才稀缺，资深策划总监年薪 30-60 万；头部案例操盘手收入更高。','策划助理 → 策划经理 → 创意总监 → 品牌咨询合伙人。','AI 生成创意素材、短剧营销、私域内容运营是策划新赛道。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('动画设计师','文化传媒 · 动漫','[\"进行角色/场景原画设计，绘制分镜与动态分镜\", \"使用 Maya/Blender/Spine 完成建模、绑定、动画制作\"]','动画设计师是造梦师，从国产动画电影到游戏 CG、虚拟主播，用一帧帧画面赋予角色生命，是中国动漫崛起浪潮的核心创作者。','[\"美术功底与角色设计\", \"Maya/Blender/三维动画流程\", \"运动规律与表演设计\", \"后期合成（AE/Nuke）\"]','[\"艺术审美\", \"耐心与细节控\", \"团队协作（导演/原画/后期）\", \"讲故事能力\"]','国产动画票房屡创新高，游戏与短视频动画需求旺盛，资深动画师年薪 20-45 万；绑定与特效方向技术人才溢价明显。','动画师 → 资深动画师 → 动画指导 → 导演/艺术总监。','AI 辅助中间帧生成、虚拟数字人、实时渲染动画正在改变生产流程。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('播音主持人','文化传媒 · 广播电视','[\"主持新闻播报、综艺、访谈、直播等各类节目\", \"完成配音、串场与现场把控，处理突发状况\"]','播音主持人是声音与舞台的主人，从电视新闻到网络直播、有声书，用语言艺术传递信息与情感，是传媒领域最具魅力的职业之一。','[\"普通话一级甲等与播音发声功底\", \"即兴口语表达与控场\", \"稿件播读与新闻敏感\", \"音视频设备与直播技术\"]','[\"镜头感与亲和力\", \"文化底蕴与知识储备\", \"临场应变\", \"形体与镜头表现\"]','媒体融合催生网络主播、声音主播等新场景，头部商业主持与声音博主年收入数十万至数百万；传统媒体岗位竞争白热化。','主持人 → 资深主持/主播 → 节目制作人 → 传媒公司合伙人。','AI 数字人播音兴起，真人主持的创意表达与情感连接价值反而提升。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('土木工程师','建筑工程 · 土木工程','[\"进行建筑结构设计计算，编制结构施工图\", \"施工现场技术管理，解决地基、主体施工技术问题\"]','土木工程师是城市建设的奠基者，从摩天大楼到跨海大桥，把图纸变为矗立大地的实体工程，是基建强国的中坚力量。','[\"结构力学与结构设计原理\", \"PKPM/YJK 等结构计算软件\", \"施工工艺与验收规范\", \"BIM 建模与协同\"]','[\"现场协调能力\", \"规范理解应用\", \"质量安全意识\", \"图纸表达能力\"]','基建进入存量更新时代，市政更新、城中村改造、海外工程带来新需求，资深结构工程师年薪 25-50 万，注册结构工程师持证溢价高。','技术员 → 专业工程师 → 项目总工程师 → 技术中心主任。','智能建造（建筑机器人）、城市更新设计、工程数字化交付是转型方向。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('造价工程师','建筑工程 · 工程造价','[\"编制工程量清单与招标控制价，审核结算与决算\", \"全过程成本管控，处理工程变更与索赔\"]','造价工程师是工程成本的精算师，让每一分建设资金花得明白，从招投标到竣工结算贯穿工程全周期，是建筑行业越老越吃香的技术岗位。','[\"工程量清单计价规范\", \"广联达等造价软件\", \"施工工艺与识图\", \"合同法与招投标法规\"]','[\"数字敏感度\", \"细致严谨\", \"谈判沟通能力\", \"多方协调能力\"]','造价咨询行业集中度提升，一级造价工程师年薪 20-40 万，全过程工程咨询与司法鉴定方向专家收入更高。','造价员 → 造价工程师 → 成本经理 → 咨询公司合伙人。','AI 算量、BIM 量价一体化让造价工作提质增效，复合型人才更受青睐。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('给排水工程师','建筑工程 · 市政工程','[\"设计建筑给水排水、消防水系统与市政管网\", \"负责供水/污水处理工程工艺设计与运行调试\"]','给排水工程师守护城市水脉，从自来水厂到污水厂、从建筑消防到海绵城市，保障水安全与水环境，是市政与环境交叉的重要专业。','[\"给排水管网与水力计算\", \"水质工程学与处理工艺\", \"AutoCAD/天正给排水设计\", \"水处理工程调试与运营\"]','[\"规范应用能力\", \"现场调试能力\", \"环保法规理解\", \"多方协调能力\"]','城市更新与水利投资加大，给排水设计人才缺口稳定；注册公用设备工程师（给水排水）持证者年薪 30 万以上。','设计员 → 专业负责人 → 所总工 → 设计院管理层。','智慧水务、再生水利用、城市内涝治理是专业热点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('风景园林设计师','建筑工程 · 园林景观','[\"进行公园、住区、文旅项目的景观方案与施工图设计\", \"配置植物群落，把控景观效果与成本控制\"]','风景园林设计师是户外空间的艺术家，让人与自然在公园、街区、庭院中和谐共处，是美丽中国与城市双修战略下的创意岗位。','[\"景观设计理论与表现（SU/Lumion）\", \"植物配置与生态学基础\", \"施工图设计与工程做法\", \"文旅策划基础\"]','[\"艺术审美与空间感\", \"手绘与软件表达能力\", \"现场把控能力\", \"成本控制意识\"]','景观行业向生态修复与文旅运营转型，资深设计师年薪 20-40 万；乡村振兴与矿山修复项目带来新机会。','设计师 → 主创设计师 → 设计总监 → 景观事务所合伙人。','口袋公园、城市绿道、生态碳汇景观成为设计新热点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('测绘工程师','工程技术 · 测绘地信','[\"使用全站仪、GPS/北斗、无人机进行外业测量采集\", \"处理遥感影像与点云数据，编制地形图与专题图\"]','测绘工程师是时空信息的采集者，从珠峰高程测量到智慧城市三维建模，用精准坐标描绘山河，北斗组网让国产测绘装备全面崛起。','[\"测量学原理与仪器操作\", \"GNSS 定位与无人机航测\", \"CASS/ArcGIS 数据处理\", \"遥感影像解译\"]','[\"野外作业能力\", \"数据处理耐心\", \"安全意识\", \"空间思维\"]','实景三维中国、智慧城市、自动驾驶高精地图带动需求，注册测绘师年薪 20-40 万，无人机测绘与 GIS 开发方向溢价高。','测绘员 → 项目负责人 → 总工 → 测绘院管理岗。','卫星遥感商业化、激光雷达点云、时空大数据是行业增长引擎。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('材料工程师','工程技术 · 新材料','[\"研发金属/高分子/陶瓷/复合材料的新配方与新工艺\", \"进行材料性能测试与失效分析，支撑产品选材\"]','材料工程师是制造升级的幕后英雄，芯片的硅、飞机的复材、电池的锂电，所有硬核产品的突破都始于材料创新。','[\"材料科学基础与相图分析\", \"材料制备与表征技术（XRD/SEM）\", \"失效分析与可靠性评估\", \"工艺放大与中试能力\"]','[\"实验设计与数据分析\", \"专利撰写能力\", \"跨学科协作\", \"严谨细致\"]','国产替代加速，半导体材料、新能源材料、生物医用材料方向人才紧缺，资深材料工程师年薪 30-60 万，研究院专家更高。','研发工程师 → 高级研发 → 首席研究员 → 技术总监。','AI 材料计算（材料基因组）、固态电池材料、气凝胶等前沿材料持续涌现。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('地质工程师','工程技术 · 地质勘察','[\"开展野外地质调查与钻探编录，查明工程地质条件\", \"进行矿产/油气资源评价与储量估算\"]','地质工程师是地球奥秘的探索者，从铁路选线到矿山开采、从城市地灾防治到能源勘查，用专业知识读懂大地，保障工程安全。','[\"普通地质学与构造地质学\", \"岩土工程勘察规范\", \"地质制图与三维建模（3DMine 等）\", \"地质灾害评估\"]','[\"野外作业与吃苦耐劳\", \"空间分析能力\", \"报告编写能力\", \"安全意识\"]','能源资源保障与重大工程建设支撑稳定需求，注册土木工程师（岩土）持证者年薪 30-50 万；城市地质与地灾防治岗位受重视。','技术员 → 项目负责 → 总工 → 地勘单位管理岗。','深地深海探测、地热能开发、数字孪生矿山是地质工作新前沿。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('水利工程师','工程技术 · 水利水电','[\"设计水库、大坝、堤防、水闸等水利工程建筑物\", \"编制防洪规划，开展水文计算与水资源配置\"]','水利工程师是江河安澜的守护者，从三峡工程到灌区改造、从防洪调度到抽水蓄能，在气候变化背景下肩负越来越重的使命。','[\"水力学与结构力学\", \"水文分析与水利计算\", \"水工建筑物设计\", \"洪水模拟与调度\"]','[\"系统思维\", \"规范应用能力\", \"多方协调（流域/地方/生态）\", \"责任担当\"]','国家水网重大工程全面推进，水利投资连续超万亿，水利设计院与建管单位需求旺盛，资深水利工程师年薪 25-45 万。','设计员 → 专业负责 → 项目总工 → 设计院总工/流域机构管理岗。','智慧水利（数字孪生流域）、抽水蓄能、生态水利工程是未来主线。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('物流规划师','交通物流 · 物流规划','[\"设计仓储网络布局与配送线路，优化运输方案\", \"测算物流成本，建设物流信息化系统\"]','物流规划师是实体经济的血管设计师，用运筹学优化货物的仓储、运输与配送，让电商包裹与制造供应链高效流动。','[\"运筹学与网络优化\", \"仓储管理与 WMS 系统\", \"运输管理与 TMS 系统\", \"物流成本测算\"]','[\"数据分析能力\", \"系统规划思维\", \"供应商管理能力\", \"抗压能力\"]','物流总额持续增长，具备数字化规划能力的人才稀缺，资深物流规划师年薪 20-40 万；跨境电商物流与冷链方向溢价。','物流专员 → 规划主管 → 物流经理 → 供应链总监。','智慧物流园区、无人机配送、绿色物流是规划新课题。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('供应链管理师','交通物流 · 供应链','[\"制定采购计划与供应商策略，管理供应商全生命周期\", \"监控库存与需求预测，平衡缺货与积压\"]','供应链管理师是产业链的组织者，从一颗芯片到整车下线，用计划与协同管理物料流、信息流与资金流，是制造业降本增效的关键角色。','[\"需求预测与 S&OP 流程\", \"采购谈判与供应商管理\", \"库存控制与仓储管理\", \"ERP/SAP 系统实操\"]','[\"全局思维\", \"数据分析（Excel/SQL）\", \"谈判能力\", \"跨部门推动力\"]','供应链安全上升为国家战略，供应链管理师供不应求，年薪 25-50 万；半导体、医药、汽车行业高端人才溢价明显。','计划/采购专员 → 供应链主管 → 供应链经理 → 供应链总监（CSCO）。','供应链数字化孪生、韧性供应链、绿色供应链是升级方向。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('民航飞行员','交通物流 · 航空运输','[\"执行航班飞行任务，完成航前准备与飞机检查\", \"处置飞行中的特情与天气变化，保障飞行安全\"]','民航飞行员是云端之上的职业巅峰，驾驶百吨级客机跨洲越洋，以高度的专业与责任守护每一位旅客的安全，是高收入高荣誉的职业代表。','[\"飞行理论与气象学\", \"机型系统知识与模拟机训练\", \"标准操作程序（SOP）\", \"特情处置与决策能力\"]','[\"心理素质稳定\", \"团队配合（机组资源管理）\", \"英语陆空通话\", \"纪律性与责任感\"]','民航机队持续扩张，机长年薪 80-200 万，副驾驶 30-60 万；成熟机长与教员长期处于紧缺状态。','学员 → 副驾驶 → 机长 → 教员/检查员/管理岗。','国产大飞机 C919 规模化运营、货运航空发展带来新机遇。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('空中乘务员','交通物流 · 航空服务','[\"保障客舱安全，执行应急设备检查与安全演示\", \"提供客舱服务，处置旅客突发状况与投诉\"]','空中乘务员是蓝天上的微笑使者，以专业服务让旅途舒适安心，是民航服务品质的直接代表，也是年轻人向往的职业窗口。','[\"客舱安全与应急设备\", \"服务礼仪与沟通技巧\", \"急救知识与应急处置\", \"多语言沟通能力\"]','[\"亲和力与形象气质\", \"情绪管理\", \"团队协作\", \"跨文化理解\"]','国际航线复苏带动需求，乘务长年薪 20-40 万；公务机与高端服务方向收入更高，职业寿命向地面管理岗延伸。','乘务员 → 乘务长 → 主任乘务长 → 客舱管理/培训岗。','个性化客舱服务、健康管理（高原/长航线）、数字化服务工具是提升方向。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('光伏系统工程师','能源环保 · 新能源','[\"设计光伏电站系统方案，进行发电量仿真与设备选型\", \"解决并网接入、阴影遮挡与系统效率优化问题\"]','光伏系统工程师是双碳目标的一线建设者，把阳光转化为清洁电力，从户用屋顶到戈壁基地，撑起中国光伏全球第一的产业版图。','[\"光伏发电原理与系统 design\", \"PVsyst 等仿真软件\", \"电气设计与并网规范\", \"组件/逆变器选型与匹配\"]','[\"系统设计能力\", \"现场勘查能力\", \"数据分析（发电量评估）\", \"安全规范意识\"]','光伏装机全球领先，系统设计与运维人才缺口大，资深工程师年薪 20-40 万；海外项目与储能融合设计方向溢价。','技术员 → 系统工程师 → 项目总工 → 新能源设计院/投资开发岗。','光储一体化、钙钛矿新技术、智能运维机器人是行业新增长点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('风电工程师','能源环保 · 新能源','[\"进行风资源评估与微观选址，设计风机基础与电气接入\", \"负责风机吊装调试、运维检修与技改提效\"]','风电工程师驭风而行，在大漠、海上建设清洁能源基地，中国风电装机容量全球第一，大兆瓦机组与深远海风电持续突破。','[\"空气动力学与风资源评估\", \"风力发电机组原理\", \"电气接入与 SCADA 系统\", \"高空作业与吊装安全\"]','[\"现场作业能力\", \"数据分析（功率曲线评估）\", \"机械电气综合知识\", \"吃苦耐劳\"]','陆上风电平价上网后进入稳增期，海上风电爆发带来大量岗位，资深风电工程师年薪 20-40 万，海上运维工程师待遇上浮 30%。','运维工程师 → 技术主管 → 风场场长 → 区域技术经理。','15MW+ 大兆瓦机组、漂浮式海上风电、风电制氢是技术前沿。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('环境工程师','能源环保 · 环境治理','[\"设计废气、废水、固废治理工程方案与工艺流程\", \"开展环境影响评价与竣工环保验收\"]','环境工程师是绿水青山的修复师，从黑臭水体治理到工业废气净化、土壤修复，用工程技术解决环境污染问题，是美丽中国建设的主力军。','[\"水/气/固废污染治理工艺\", \"环评技术导则与法规\", \"CAD 工艺设计与计算\", \"环境监测与验收流程\"]','[\"工艺设计能力\", \"法规政策理解\", \"项目协调能力\", \"现场问题解决\"]','环保投资持续加码，EOD 模式与流域治理项目落地，资深环境工程师年薪 20-40 万；土壤修复与 VOCs 治理方向紧缺。','工艺设计 → 项目经理 → 技术总监 → 环保公司合伙人。','减污降碳协同、新污染物治理、智慧环保监测是政策热点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('核能工程师','能源环保 · 核能','[\"参与核电站反应堆系统设计、核安全分析与设备选型\", \"负责核电工程建设管理或运行技术支持\"]','核能工程师是和平利用原子能的掌控者，以最高安全标准设计建造核电站，中国在建核电机组全球第一，核能在双碳目标中承担基荷使命。','[\"核反应堆物理与热工水力\", \"核安全法规与纵深防御理念\", \"核电系统设计与分析软件\", \"辐射防护与应急知识\"]','[\"极致严谨\", \"系统安全思维\", \"多学科综合能力\", \"责任心与使命感\"]','核电核准常态化，每年 6-10 台机组开工，核能工程师供不应求，年薪 20-45 万；核聚变研发方向顶尖人才待遇优厚。','现场工程师 → 系统设计 → 项目总工 → 核电集团技术管理岗。','华龙一号批量化、小型模块化反应堆（SMR）、可控核聚变（ITER/CFETR）是战略方向。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('农艺师','农林牧渔 · 现代农业','[\"制定作物种植方案，指导良种选育与田间管理\", \"测土配方施肥，开展病虫害绿色防控\"]','农艺师是把论文写在大地上的田间科学家，用良种良法良技提高粮食产量与品质，是保障国家粮食安全的技术骨干。','[\"作物栽培学与育种知识\", \"土壤肥料与植保技术\", \"田间试验与数据统计\", \"智慧农业设备应用\"]','[\"田间实践能力\", \"数据分析能力\", \"农民培训能力\", \"吃苦耐劳\"]','高标准农田建设与农业社会化服务推进，农艺师需求稳定增长，年薪 12-30 万；种业公司与智慧农业企业技术岗溢价高。','技术员 → 农艺师 → 高级农艺师 → 农业公司技术总监/推广站负责人。','生物育种产业化、无人农场、AI 虫情测报让传统农艺插上科技翅膀。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('畜牧兽医师','农林牧渔 · 畜牧兽医','[\"开展动物疫病防控、诊断治疗与检疫检验\", \"指导养殖场饲养管理、繁殖育种与饲料配方\"]','畜牧兽医师是动物健康的守护者，从规模养殖场到宠物医院，保障肉蛋奶安全与伴侣动物健康，现代畜牧业高质量发展的关键人才。','[\"动物解剖生理与病理学\", \"兽医临床诊断与手术\", \"动物防疫与检疫法规\", \"饲料营养与配方设计\"]','[\"临床操作能力\", \"生物安全意识\", \"养殖场沟通能力\", \"应急处理能力\"]','规模化养殖与宠物经济双轮驱动，执业兽医师年薪 15-40 万；宠物医疗专科医生与大型养殖场技术总监收入可观。','驻场兽医/宠物医生 → 主治兽医师 → 技术总监 → 动保公司/连锁宠物医院合伙人。','宠物专科医疗、智慧养殖（环境智控）、减抗替抗技术是未来重点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('水产养殖工程师','农林牧渔 · 水产','[\"设计养殖模式与水质调控方案，指导苗种培育\", \"研究饲料投喂策略与病害防治，提升成活率\"]','水产养殖工程师是蓝色粮仓的建设者，从池塘精养到深远海网箱、工厂化循环水养殖，让中国人吃上更多优质水产品。','[\"水产养殖学与水环境化学\", \"水质检测与调控技术\", \"鱼类营养与饲料学\", \"养殖工程设计与装备\"]','[\"现场管理经验\", \"数据分析（生长模型）\", \"病害诊断能力\", \"成本控制能力\"]','深远海养殖上升为国家战略，智能渔场建设加速，资深养殖工程师年薪 15-35 万；循环水系统（RAS）设计人才稀缺。','养殖场技术员 → 场长 → 技术总监 → 水产企业合伙人。','深远海智能网箱、循环水养殖、水产种业振兴是行业主线。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('林业工程师','农林牧渔 · 林业','[\"开展森林资源调查与规划设计，编制采伐/抚育方案\", \"组织造林绿化、森林经营与碳汇计量\"]','林业工程师是绿水青山的守护者，从国土绿化到森林碳汇、从国家公园到林下经济，用可持续经营理念经营森林生态系统。','[\"森林培育与经理学\", \"遥感与 GIS 资源调查\", \"林业法规与采伐限额\", \"碳汇计量与监测方法\"]','[\"野外调查能力\", \"规划设计能力\", \"生态思维\", \"政策理解\"]','双碳战略下林业碳汇潜力巨大，林业工程师在碳汇开发、生态修复领域需求上升，年薪 12-30 万，碳汇项目专家溢价明显。','技术员 → 工程师 → 高级工程师 → 林场/林业设计院负责人。','国家储备林建设、林业碳汇交易、森林康养是发展新机遇。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('高校辅导员','教育科研 · 高校管理','[\"负责学生思想政治教育与日常事务管理\", \"开展心理健康排查、危机干预与就业指导\"]','高校辅导员是大学生成长成才的引路人，亦师亦友陪伴青年度过关键四年，是高校立德树人一线最重要的力量之一。','[\"思想政治教育方法论\", \"大学生心理健康教育\", \"危机干预流程\", \"就业指导与生涯规划\"]','[\"谈心谈话与共情能力\", \"活动组织能力\", \"文字表达能力\", \"应急处突能力\"]','高校专职辅导员配备比例政策刚性要求，岗位需求稳定，编制内辅导员综合待遇良好，职业发展可走管理或思政教师双通道。','辅导员 → 学工办主任 → 学院党委副书记 → 学生工作部副部长。','数字化思政、精准资助、一站式学生社区建设是改革方向。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('教研员','教育科研 · 教学研究','[\"研究课程标准与教材，指导一线教师课堂教学\", \"组织区域教研活动、命题质量监测与教师培训\"]','教研员是连接教育理论与课堂实践的桥梁，用专业研究带动区域教学质量提升，是教师群体中专业成长的引领者。','[\"学科课程标准与教材体系\", \"课堂观察与评课技术\", \"教育测量与命题技术\", \"课题研究方法\"]','[\"教学示范能力\", \"培训讲座能力\", \"数据分析（质量监测）\", \"组织协调\"]','新课改深化背景下教研体系加强，特级教师级教研员影响力大；职业稳定，学术声望高，优秀者可晋升教研部门负责人。','骨干教师 → 教研员 → 资深教研员 → 教研室主任。','素养导向教学评价、AI 课堂分析、跨学科主题学习是教研热点。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('教学设计师','教育科研 · 教育科技','[\"分析学习目标与学习者特征，设计课程结构与教学活动\", \"制作交互课件与数字化教学资源，评估教学效果\"]','教学设计师是教与学的架构师，把教育理论与媒体技术结合，设计出让知识高效传递的课程体验，在线教育与企业培训都需要。','[\"学习科学与教学设计理论\", \"课程开发流程\", \"交互课件制作（Articulate/H5）\", \"学习效果评估方法\"]','[\"产品思维\", \"视觉表达能力\", \"用户需求洞察\", \"跨团队协作\"]','教育数字化战略推动需求增长，资深教学设计师年薪 25-45 万；AI 课程设计、企业大学、职业教育方向机会多。','课程设计师 → 资深设计师 → 教学产品负责人 → 教育科技公司管理层。','AI 个性化学习路径、游戏化学习、多模态数字教材是设计前沿。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
INSERT INTO `career_lib` (`name`,`category`,`duties`,`content`,`skills_pro`,`skills_gen`,`prospect`,`path`,`trend`) VALUES ('特殊教育教师','教育科研 · 特殊教育','[\"为视力/听力/智力障碍及自闭症儿童制定个别化教育计划（IEP）\", \"开展康复训练、行为干预与融合教育支持\"]','特殊教育教师是用爱与专业点亮特殊孩子世界的燃灯者，让每个孩子都能享有公平而有质量的教育，是教师队伍中最需要耐心与爱心的岗位。','[\"特殊教育理论与障碍分类\", \"IEP 制定与执行\", \"行为分析与干预（ABA 基础）\", \"康复训练技术与评估\"]','[\"爱心与耐心\", \"观察评估能力\", \"家校沟通能力\", \"情绪稳定性\"]','特殊教育生均经费保障加强，特教教师待遇倾斜政策明确，岗位缺口大、职业稳定性极高，是事业编制内的紧缺专业。','特教教师 → 骨干教师 → 资源中心负责人 → 特殊教育学校管理岗。','融合教育普及、AI 辅助沟通设备、早期干预体系完善带来专业新需求。') ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `duties`=VALUES(`duties`), `content`=VALUES(`content`), `skills_pro`=VALUES(`skills_pro`), `skills_gen`=VALUES(`skills_gen`), `prospect`=VALUES(`prospect`), `path`=VALUES(`path`), `trend`=VALUES(`trend`);
--> statement-breakpoint
